function studyWeek(){const sessions=active('session');const c=card('<strong>Minha semana</strong>');const row=document.createElement('div');row.className='study-week';for(let i=6;i>=0;i--){const d=shift(today(),-i),b=document.createElement('span');b.textContent=new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short'}).slice(0,3);if(sessions.some(x=>x.date===d))b.className='studied';row.append(b)}c.append(row)}
