async function backup(verified=false){if(localStorage.getItem('pin')&&verified!==true){askAreaPin(()=>backup(true));return}const data=[];for(const r of rows){const attachments=[];for(const a of r.attachments||[]){const b=new Uint8Array(await a.blob.arrayBuffer());let s='';for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode(...b.subarray(i,i+8192));attachments.push({name:a.name,type:a.blob.type,data:btoa(s)})}data.push({...r,attachments})}const blob=new Blob([packBackup(JSON.stringify({format:'hikki-notes',version:1,items:data}))],{type:'application/zip'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='hikki-backup-'+today()+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),30000);localStorage.setItem('lastBackup',today())}async function restore(file){const b=JSON.parse(await unpackBackup(file));if(b.format!=='hikki-notes'||b.version!==1||!Array.isArray(b.items))throw Error('Backup incompatível');const ids=new Set();const items=b.items.map(r=>{if(!r||typeof r.id!=='string'||!r.id||ids.has(r.id)||!Object.hasOwn(types,r.type)|| (r.attachments!=null&&!Array.isArray(r.attachments)))throw Error('Registro inválido');ids.add(r.id);for(const k of ['title','body','category','date','time','tasks','parent','link'])if(r[k]!=null&&typeof r[k]!=='string')throw Error('Campo inválido: '+k);return {...r,attachments:(r.attachments||[]).map(a=>{if(!a||typeof a.name!=='string'||typeof a.data!=='string'||typeof a.type!=='string')throw Error('Anexo inválido');return {name:a.name,blob:new Blob([Uint8Array.from(atob(a.data),c=>c.charCodeAt(0))],{type:a.type})}})}});if(!confirm('Mesclar backup com os dados atuais? Registros com o mesmo ID serão substituídos.'))return;await write(items);dlg.close();render()}
async function hash(s){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s))),x=>x.toString(16).padStart(2,'0')).join('')}function lock(){clearCalendarUrls();locked=true;dlg.close();$('#nav').replaceChildren();main.innerHTML='<h1>Hikki Notes</h1><p>Digite seu PIN</p>';const i=document.createElement('input');i.type='password';main.append(i);add(main,'Desbloquear',async()=>{if(await hash(i.value)===localStorage.getItem('pin')){locked=false;render()}else hikkiAlert('PIN incorreto')},'primary')}
function updateClock(){const e=$('#studyElapsed'),start=Number(localStorage.getItem('studyStart'));if(e&&start){const n=Math.max(0,Math.floor((Date.now()-start)/1000));e.textContent=[Math.floor(n/3600),Math.floor(n/60)%60,n%60].map(x=>String(x).padStart(2,'0')).join(':')}}setInterval(updateClock,1000);function notificationPayload(r){const visible=r.notificationPrivacy==='public'&&!r.privateReminder&&!areaNeedsPin(3);return [visible?(r.title||'Lembrete'):'Hikki Notes',{body:visible?(r.body||'Você tem um lembrete pendente.'):'Você tem um lembrete pendente. Abra o aplicativo para visualizar.',tag:r.id,icon:'./icon-192.png',timestamp:Date.now()}]}let checkingAlerts=false;async function checkAlerts(){if(nativeAlerts())return;if(!db||checkingAlerts||!localStorage.getItem('reminderAlerts')||!('Notification'in window)||Notification.permission!=='granted')return;checkingAlerts=true;try{const now=new Date();for(const r of rows.filter(r=>r.type==='reminder'&&!r.deleted)){if(r.done||!r.date||!r.time)continue;const due=new Date(r.date+'T'+r.time);const key=r.date+'T'+r.time;if(!Number.isFinite(+due)||due>now||r.alerted===key)continue;const reg=await navigator.serviceWorker?.getRegistration();if(!reg)continue;const latest=get(r.id);if(!latest||latest.deleted||latest.done||latest.date+'T'+latest.time!==key)continue;await reg.showNotification(...notificationPayload(latest));const current=get(r.id);if(current&&!current.deleted&&current.date+'T'+current.time===key)await save({...current,alerted:key})}}catch(e){console.warn(e)}finally{checkingAlerts=false}}setInterval(checkAlerts,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkAlerts()});
