function settings(){if(locked)return;resetDialog();const h=document.createElement('h2');h.textContent='Ajustes';dlg.append(h);const version=document.createElement('small');version.textContent=(localStorage.getItem('hikkiTheme')==='midnight'?'Midnight':'Forest')+' Edition · R35';dlg.append(version);add(dlg,'🌿 Forest Edition',()=>{localStorage.setItem('hikkiTheme','forest');applyTheme();dlg.close();render();settings()});add(dlg,'☾ Midnight Edition',()=>{localStorage.setItem('hikkiTheme','midnight');applyTheme();dlg.close();render();settings()});add(dlg,'↻ Verificar atualizações',async()=>{const reg=await navigator.serviceWorker?.getRegistration();if(!reg)return hikkiAlert('Atualização indisponível');await reg.update();if(reg.waiting){dlg.close();document.querySelector('#updateNotice')?.click()}else hikkiAlert(reg.installing?'Atualização em preparação. Aguarde o aviso.':'Nenhuma atualização pronta no momento.')});add(dlg,localStorage.getItem('noMotion')?'Ativar animações':'Desativar animações',()=>{if(localStorage.getItem('noMotion'))localStorage.removeItem('noMotion');else localStorage.setItem('noMotion','1');dlg.close();settings()});const p=document.createElement('p');p.textContent='Backup completo local (ZIP). Último backup: '+(localStorage.getItem('lastBackup')||'Nunca');dlg.append(p);add(dlg,'Exportar backup',backup,'primary');add(dlg,localStorage.getItem('reminderAlerts')?'Desativar notificações':'Ativar notificações',async()=>{if(localStorage.getItem('reminderAlerts'))localStorage.removeItem('reminderAlerts');else if(nativeAlerts()){if(!await nativePermission())return hikkiAlert('Permissão não concedida');localStorage.setItem('reminderAlerts','1')}else{if(!('Notification'in window))return hikkiAlert('Notificações indisponíveis neste navegador');if(await Notification.requestPermission()!=='granted')return hikkiAlert('Permissão não concedida');localStorage.setItem('reminderAlerts','1');await checkAlerts()}await syncNativeAlerts();dlg.close();settings()});add(dlg,'Consultar armazenamento',async()=>{const e=await navigator.storage?.estimate?.();if(!e)return hikkiAlert('Estimativa indisponível');const mb=n=>(n/1048576).toFixed(1)+' MB';hikkiAlert('Uso estimado: '+mb(e.usage||0)+'\nCota estimada: '+mb(e.quota||0)+'\nRegistros ativos: '+rows.filter(r=>!r.deleted).length+'\nNa lixeira: '+rows.filter(r=>r.deleted).length)});const i=document.createElement('input');i.type='file';i.accept='.zip,.json';i.onchange=act(()=>restore(i.files[0]));dlg.append(i);add(dlg,'Solicitar armazenamento persistente',async()=>hikkiAlert(await navigator.storage?.persist?.()?'Armazenamento persistente concedido':'Não concedido pelo navegador'));add(dlg,localStorage.getItem('compressImages')?'Desativar redução de imagens':'Ativar redução de imagens',()=>{if(localStorage.getItem('compressImages'))localStorage.removeItem('compressImages');else localStorage.setItem('compressImages','1');dlg.close();settings()});add(dlg,'Configurar PIN',pinSettings);add(dlg,'Lixeira',()=>{resetDialog();const deleted=rows.filter(r=>r.deleted&&recordVisible(r)&&!r.privateReminder);if(!deleted.length){const p=document.createElement('p');p.textContent='A lixeira está vazia.';dlg.append(p)}deleted.forEach(r=>add(dlg,'Restaurar: '+title(r),async()=>{await save({...r,deleted:false});dlg.close();render()}));add(dlg,'Fechar',()=>dlg.close())});add(dlg,'Fechar',()=>dlg.close());organizeSettings();dlg.showModal()}
