let hikkiInstallPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();hikkiInstallPrompt=e});window.addEventListener('appinstalled',()=>{hikkiInstallPrompt=null});async function installHikki(){if(window.matchMedia('(display-mode: standalone)').matches||navigator.standalone)return hikkiAlert('O Hikki Notes já está aberto como aplicativo.');if(hikkiInstallPrompt){const p=hikkiInstallPrompt;hikkiInstallPrompt=null;await p.prompt();await p.userChoice;return}hikkiAlert('No Chrome, abra o menu de três pontos e escolha Instalar aplicativo ou Adicionar à tela inicial. Se já instalou, abra pelo ícone do Hikki Notes.');}

let devTimer=null;
function developerPanel(){resetDialog();dlg.classList.add('settings-screen');const h=document.createElement('h2');h.textContent='Modo desenvolvedor';dlg.append(h);const status=document.createElement('p');status.className='muted';status.setAttribute('role','status');dlg.append(status);const report=async()=>{const reg=await navigator.serviceWorker?.getRegistration();status.textContent='Permissão: '+('Notification'in window?Notification.permission:'indisponível')+' · Service worker: '+(reg?.active?'ativo':'inativo')+' · Lembretes: '+(localStorage.getItem('reminderAlerts')?'ativados':'desativados')+' · Modo: '+(matchMedia('(display-mode: standalone)').matches?'app instalado':'navegador')};const log=document.createElement('p');log.setAttribute('role','status');log.className='dev-log';const send=async(priv)=>{try{if(nativeAlerts()){if(!await nativePermission())throw Error('Permissão não concedida');const [title,opts]=notificationPayload({title:'Lembrete de teste',body:'Aviso de teste',notificationPrivacy:priv?'private':'public'});await nativeAlerts().schedule({notifications:[{id:99,title,body:opts.body,schedule:{at:new Date(Date.now()+1000)}}]});log.textContent='Teste nativo agendado.';return}if(!('Notification'in window))throw Error('API indisponível');if(Notification.permission!=='granted')throw Error('Autorize as notificações primeiro');const reg=await navigator.serviceWorker?.getRegistration();if(!reg?.active)throw Error('Service worker inativo');const payload=notificationPayload({id:'dev-test-'+Date.now(),title:'Lembrete de teste',body:'Este é um aviso de teste do Hikki Notes.',privacy:priv?'private':'public',notificationPrivacy:priv?'private':'public'});await reg.showNotification(payload[0],{...payload[1],tag:'hikki-dev-'+Date.now()});log.textContent='Solicitação aceita pelo navegador às '+new Date().toLocaleTimeString('pt-BR')+'. Confira a bandeja de notificações.'}catch(e){log.textContent='Falha: '+e.message}};add(dlg,'Solicitar permissão',async()=>{try{if(!('Notification'in window))throw Error('API indisponível');await Notification.requestPermission();await report()}catch(e){log.textContent=e.message}});add(dlg,'Testar notificação pública',()=>send(false));add(dlg,'Testar notificação privada',()=>send(true));add(dlg,'Testar em 10 segundos',()=>{if(nativeAlerts()){nativePermission().then(ok=>{if(ok)return nativeAlerts().schedule({notifications:[{id:98,title:'Hikki Notes',body:'Teste nativo de 10 segundos',schedule:{at:new Date(Date.now()+10000),allowWhileIdle:true}}]})}).catch(console.warn);log.textContent='Teste nativo agendado para 10 segundos.';return}clearTimeout(devTimer);log.textContent='Teste agendado para 10 segundos. O navegador pode suspender o temporizador em segundo plano.';devTimer=setTimeout(()=>{devTimer=null;send(false)},10000)});add(dlg,'Cancelar teste agendado',()=>{clearTimeout(devTimer);devTimer=null;nativeAlerts()?.cancel({notifications:[{id:98},{id:99}]}).catch(console.warn);log.textContent='Teste cancelado.'});add(dlg,'Atualizar diagnóstico',report);dlg.append(log);add(dlg,'Voltar aos ajustes',()=>{dlg.close();settings()});report()}

function hikkiAlert(message){const d=document.createElement('dialog');d.className='hikki-message';const h=document.createElement('h2');h.textContent=String(message)==='PIN incorreto'?'PIN incorreto':'Hikki Notes';const p=document.createElement('p');p.textContent=String(message)==='PIN incorreto'?'Confira seu PIN e tente novamente.':String(message);const b=document.createElement('button');b.className='primary';b.textContent='Entendido';b.onclick=()=>d.close();d.append(h,p,b);document.body.append(d);d.addEventListener('close',()=>d.remove(),{once:true});d.showModal()}

function nativeAlerts(){return window.Capacitor?.isNativePlatform?.()?window.Capacitor.Plugins.LocalNotifications:null}
async function nativePermission(){const p=nativeAlerts();if(!p)return false;return (await p.requestPermissions()).display==='granted'}
let nativeQueue=Promise.resolve();function syncNativeAlerts(){nativeQueue=nativeQueue.catch(console.warn).then(async()=>{const p=nativeAlerts();if(!p)return;const pending=await p.getPending();const ours=pending.notifications.filter(n=>n.id>=100000&&n.id<2000000000);if(ours.length)await p.cancel({notifications:ours.map(n=>({id:n.id}))});if(!localStorage.getItem('reminderAlerts')||(await p.checkPermissions()).display!=='granted')return;const used=new Set();const notifications=[];for(const r of rows){if(r.type!=='reminder'||r.deleted||r.done||!r.date||!r.time)continue;const at=new Date(r.date+'T'+r.time);if(!Number.isFinite(+at)||+at<=Date.now())continue;let id=100000+([...r.id].reduce((h,c)=>(Math.imul(h,31)+c.charCodeAt(0))>>>0,0)%1999800000);while(used.has(id))id++;used.add(id);const [title,opts]=notificationPayload(r);notifications.push({id,title,body:opts.body,schedule:{at,allowWhileIdle:true}})}if(notifications.length)await p.schedule({notifications})});return nativeQueue}

function pinSettings(){resetDialog();dlg.classList.add('settings-screen');const h=document.createElement('h2');h.textContent='Bloqueio por PIN';dlg.append(h);const old=localStorage.getItem('pin');const fieldPin=(label)=>{const l=document.createElement('label');l.textContent=label;const i=document.createElement('input');i.type='password';i.autocomplete='off';l.append(i);dlg.append(l);return i};const current=old?fieldPin('PIN atual'):null;const next=fieldPin('Novo PIN');const repeat=fieldPin('Confirmar novo PIN');const verify=async()=>!old||await hash(current.value)===old;add(dlg,old?'Mudar PIN':'Configurar PIN',async()=>{if(!await verify())return hikkiAlert('PIN incorreto');if(next.value.length<4||next.value!==repeat.value)return hikkiAlert('Use pelo menos quatro caracteres e confirme o mesmo PIN.');localStorage.setItem('pin',await hash(next.value));dlg.close();settings();hikkiAlert('PIN salvo.')},'primary');if(old)add(dlg,'Remover PIN',async()=>{if(!await verify())return hikkiAlert('PIN incorreto');if(rows.some(r=>r.privateReminder))return hikkiAlert('Retire os lembretes da área privada antes de remover o PIN.');localStorage.removeItem('pin');localStorage.removeItem('pinAreas');dlg.close();settings();hikkiAlert('Proteção removida.')});if(old)add(dlg,'Áreas protegidas',async()=>{if(!await verify())return hikkiAlert('PIN incorreto');showPinAreas()});add(dlg,'Voltar aos ajustes',()=>{dlg.close();settings()});if(!dlg.open)dlg.showModal()}

var privateView=false,areaGranted=false;
function pinAreas(){if(!localStorage.getItem('pin'))return [];try{return JSON.parse(localStorage.getItem('pinAreas')||'["all"]')}catch{return ['all']}}
function areaNeedsPin(i){return pinAreas().includes(String(i))}
function recordVisible(r){if(r.privateReminder)return tab===3&&privateView&&(!areaNeedsPin(3)||areaGranted);const i=({note:1,folder:1,diary:2,reminder:3,subject:4,unit:4,topic:4,flash:4,session:4})[r.type];return !areaNeedsPin(i)||(tab===i&&areaGranted)}
function askAreaPin(done){const d=document.createElement('dialog');d.className='hikki-message';const h=document.createElement('h2');h.textContent='Área protegida';const i=document.createElement('input');i.type='password';i.placeholder='Digite seu PIN';d.append(h,i);add(d,'Desbloquear',async()=>{if(await hash(i.value)!==localStorage.getItem('pin'))return hikkiAlert('PIN incorreto');d.close();await done()},'primary');add(d,'Cancelar',()=>d.close());document.body.append(d);d.addEventListener('close',()=>d.remove(),{once:true});d.showModal()}
function areaGate(){clearCalendarUrls();main.replaceChildren();heading('Área protegida','Informe seu PIN para continuar.');add(main,'Desbloquear',()=>askAreaPin(()=>{areaGranted=true;render()}),'primary');add(main,'Voltar ao início',()=>go(0))}
function showPinAreas(){resetDialog();const h=document.createElement('h2');h.textContent='Áreas protegidas';dlg.append(h);const fields=[];for(const [v,t] of [['all','Aplicativo inteiro'],['1','Notas'],['2','Diário'],['3','Lembretes'],['4','Estudos']]){const l=field(v,t,pinAreas().includes(v),'checkbox');fields.push(l.querySelector('input'));dlg.append(l)}add(dlg,'Salvar preferências',()=>{const values=fields.filter(i=>i.checked).map(i=>i.name);localStorage.setItem('pinAreas',JSON.stringify(values.includes('all')?['all']:values));areaGranted=false;privateView=false;dlg.close();go(0);if(values.includes('all'))lock()},'primary');add(dlg,'Cancelar',()=>{dlg.close();settings()})}

document.addEventListener('visibilitychange',()=>{if(document.hidden){areaGranted=false;privateView=false;if(pinAreas().includes('all')){if(!dlg.open)lock()}else if(areaNeedsPin(tab)||tab===3){if(!dlg.open)render()}}else if(!dlg.open&&!locked&&(areaNeedsPin(tab)||tab===3))render()});
